+                    }
+                }
+                obj->mod_elem[side] = 0;
+            }
+            continue;
+        }
+        total_w = n_stat * FIGHTSTG_HUD_MOD_STAT_STEP + n_elem * FIGHTSTG_HUD_MOD_ELEM_STEP - 1;
+        x0 = (side == 1) ? 53 : (259 - total_w);
+        fightstg_battle_menu_quad(x0 - 2, FIGHTSTG_HUD_MOD_Y, total_w + 3, 12, 2, 150, 140, 100);
+        if (!changed) {
