+                cur_x += FIGHTSTG_HUD_MOD_ELEM_STEP;
+            } else if (data->elem_mod[side][k] != NULL) {
+                data->elem_mod[side][k]->set_visible(data->elem_mod[side][k], 0);
+            }
+        }
+        obj->mod_elem[side] = mask;
