#include "object.h"
#include "heap.h"
#include "gfx.h"
#include "fightstg.h"

#include "definitive.h"

#define CALLOUT_LAYER 0x1004 /* the models' layer: draw offset (160, 120), so the screen is -160..159 x -120..119 */
