    { 'E', 10, 4, { { 0, 0, 4, 16, 0, 4 }, { 0, 4, 10, 4, 4, 10 }, { 6, 4, 9, 10, 4, 9 }, { 12, 4, 10, 16, 4, 10 } } },
    { 'A', 13, 3, { { 0, 4, 8, 16, 0, 4 }, { 0, 5, 9, 16, 9, 13 }, { 9, 3, 10, 12, 2, 11 } } },
