static void fieldmenu_bestiary_panel(Fieldmenu *obj) {
    s32 i;

    for (i = 1; i < 7; i++) {
        fieldmenu_bestiary_rect(obj, BS_PANEL_X + 6, BS_ROW_Y + i * 14 - 1, BS_PANEL_W - 12, 1, 41, 41, 115);
