int def_resist_down_mask(int side, int slot) {
    int e, mask = 0;

    side = side != 0;
    if (!def_on() || slot < 0 || resist_turns[side][slot % 3] == 0) {
        return 0;
    }
    slot %= 3;
    for (e = 0; e < 7; e++) {
        if (resist_mod[side][slot][e] < 0) {
            mask |= 1 << e;
        }
    }
    return mask;
}
