import re,glob,collections
c=collections.Counter(); maps=collections.defaultdict(set)
for f in glob.glob('src/wstag/wstag*.c'):
    m=re.search(r'wstag(\w+)\.c',f).group(1)
    for a in re.finditer(r'FieldstgPlacedActor \w+ = \{ [^,]+, [^,]+, (\d+),',open(f).read()):
        maps[int(a.group(1))].add(m)
top=sorted(maps.items(), key=lambda kv:-len(kv[1]))[:25]
for k,v in top: print(k,len(v),sorted(v)[:12])
EOF

