static int feat_on(const char *name, int def) {
    const char *v = getenv(name);
    if (v == NULL || v[0] == '\0') {
        return def;
    }
    return v[0] != '0';
}

void dw3_feats_arm(void) {
    static int armed;
    if (armed) {
        return;
