96:        stdwtitl_frame_height = sector->height;
97:    }
98:    dec->rect[0].w = dec->rect[1].w = stdwtitl_frame_width * 3 / 2;
99:    dec->rect[0].h = dec->rect[1].h = stdwtitl_frame_height;
100:    dec->slice.h = stdwtitl_frame_height;
101:    return addr;
