void stdwtitl_menu_update(StdwtitlMenu *obj) {
    switch (obj->base.state) {
    case OBJECT_STATE_INIT:
    default:
        if (obj->skip_start == 0) {
            obj->base.next_state(obj);
        } else {
            obj->base.set_state(obj, OBJECT_STATE_DONE);
        }
        obj->result = 0;
        break;
    case OBJECT_STATE_RUN:
        if (obj->base.step == 0) {
            break;
        }
        switch (obj->base.step) {
        case 1:
        default:
            if (obj->ticks++ >= 6) {
                obj->cursor = 2;
                obj->ticks = 0;
                obj->cursor_shown = 1;
                obj->base.next_step(obj);
            }
            break;
        case 2:
            if (PAD_PRESSED(3)) {
                obj->base.next_step(obj);
                obj->ticks = 0;
                sound_module.play(0x8004503C);
                obj->blink = 0;
            }
            if (++obj->ticks >= 600) {
                obj->result = 3;
            }
            break;
        case 3:
            if ((++obj->ticks & 3) == 0) {
                obj->ticks = 0;
                if (++obj->blink >= 3) {
                    obj->base.next_step(obj);
                    obj->is_open = 1;
                    obj->choice1_x = obj->choice2_x = 0x4F;
                    obj->choice1_y = obj->choice2_y = 0xA6;
                    obj->blink = 0;
                    obj->cursor_shown = 0;
                    sound_module.play(0x8004113E);
                }
            }
            break;
        case 4:
            obj->choice1_x = (stdwtitl_menu_positions[0].x - 0x4F) * obj->ticks / 15 + 0x4F;
            obj->choice1_y = (stdwtitl_menu_positions[0].y - 0xA6) * obj->ticks / 15 + 0xA6;
            obj->choice2_x = (stdwtitl_menu_positions[1].x - 0x4F) * obj->ticks / 15 + 0x4F;
            obj->choice2_y = (stdwtitl_menu_positions[1].y - 0xA6) * obj->ticks / 15 + 0xA6;
            if (++obj->ticks >= 15) {
                obj->ticks = 0;
                obj->base.next_step(obj);
            }
            break;
        case 5:
            if (++obj->ticks >= 6) {
                obj->base.set_state(obj, OBJECT_STATE_DONE);
            }
            break;
        }
        stdwtitl_menu_draw(obj);
        break;
    case OBJECT_STATE_DONE:
        switch (obj->base.step) {
        case 0:
        default:
            obj->is_open = 1;
            obj->cursor = 1;
            obj->cursor_shown = 1;
            obj->choice1_x = stdwtitl_menu_positions[0].x;
            obj->choice1_y = stdwtitl_menu_positions[0].y;
            obj->choice2_x = stdwtitl_menu_positions[1].x;
            obj->choice2_y = stdwtitl_menu_positions[1].y;
            obj->base.next_step(obj);
            break;
        case 1:
            if (PAD_PRESSED(4) || PAD_REPEAT(4)) {
                if (obj->cursor != 0) {
                    sound_module.play(0x8004513E);
                }
                obj->cursor = 0;
            }
            if (PAD_PRESSED(6) || PAD_REPEAT(6)) {
                if (obj->cursor != 1) {
                    sound_module.play(0x8004513E);
                }
                obj->cursor = 1;
            }
            if (PAD_PRESSED(13)) {
                obj->ticks = 0;
                sound_module.play(0x8004503C);
                obj->base.next_step(obj);
            }
            break;
        case 2:
            if ((++obj->ticks & 3) == 0) {
                obj->ticks = 0;
                if (++obj->blink >= 3) {
                    if (obj->cursor != 0) {
                        obj->result = 2;
                    } else {
                        obj->result = 1;
                    }
void stdwtitl_title_update(StdwtitlTitle *obj, StdwtitlTitleData *data) {
    switch (obj->base.state) {
    case OBJECT_STATE_INIT:
    default:
        obj->base.next_state(obj);
        data->background = stdwtitl_background_create(0);
        if (records_language == 0) {
            data->slide_left = stdwtitl_slide_left_create_jp(0);
            data->slide = stdwtitl_slide_create_jp(0);
            data->glow = stdwtitl_glow_create(0);
            data->shine = stdwtitl_shine_create_jp(0);
            data->menu = stdwtitl_menu_create(0);
        } else {
            data->slide_left = stdwtitl_slide_left_create_intl(0);
            data->slide = stdwtitl_slide_create_intl(0);
            data->shine = stdwtitl_shine_create_intl(0);
            data->glow = stdwtitl_glow_create(0);
            data->menu = stdwtitl_menu_create(0);
        }
        obj->ticks = 0;
        break;
    case OBJECT_STATE_RUN:
        if (stdwtitl_title_run(obj, data) != 0) {
            obj->base.set_state(obj, OBJECT_STATE_END);
        }
        break;
    case OBJECT_STATE_DONE:
        break;
    case OBJECT_STATE_END:
        sound_module.stop(0x611C0000);
        break;
    }
}

