    StdwtitlTitle *obj = object_new(stdwtitl_title_update, sizeof(StdwtitlTitle), sizeof(StdwtitlTitleData));

    obj->layer_id = 0x1000;
    obj->ot_depth = 2;
    obj->parent = parent;
    return &obj->base;
}

