                }
#endif
                if (id >= 0) {
                    if (party[k].hp <= 0) {
                        gamestate_data.digimon[id].record.stats.values[2] = 1;
                        records_battle_results.members[k].took_part = 0;
                        records_battle_results.members[k].forms[0] = 0;
                        records_battle_results.members[k].forms[1] = 0;
