                    }
                    gamestate_data.digimon[id].record.stats.values[4] = party[k].mp;
                }
            }
            data->wait.fade = fightstg_fade_create();
            data->wait.fade->start(data->wait.fade, 0, 10);
            obj->base.substep++;
        }
